-- Phase Q hardening: lifecycle RPC, Module Agent permissions and rollback recovery are applied to production.
create or replace function public.module_lifecycle_transition(p_version_id uuid,p_target_state text,p_actor_id uuid,p_reason text default null) returns public.module_versions language plpgsql security definer set search_path=public as $$ declare v public.module_versions; previous public.module_versions; begin if not public.has_role(p_actor_id,'admin') then raise exception 'Administrator authorization required'; end if; select * into v from public.module_versions where id=p_version_id for update; if not found then raise exception 'Module version not found'; end if; if p_target_state='validated' and v.lifecycle_state<>'draft' then raise exception 'Only draft module versions can be validated'; end if; if p_target_state='tested' and v.lifecycle_state<>'validated' then raise exception 'Only validated module versions can be tested'; end if; if p_target_state='active' and v.lifecycle_state<>'tested' then raise exception 'Only tested module versions can be activated'; end if; if p_target_state not in ('validated','tested','active','disabled','maintenance','rolled_back') then raise exception 'Invalid module lifecycle target'; end if; if p_target_state='active' then select * into previous from public.module_versions where module_id=v.module_id and lifecycle_state='active' and id<>v.id order by activated_at desc nulls last limit 1; if previous.id is not null then update public.module_versions set lifecycle_state='rolled_back',retired_at=now(),reason='Superseded by version '||v.version where id=previous.id; end if; update public.modules set status='active',active_version_id=v.id,manifest=v.manifest,config=v.config,updated_at=now(),last_activity_at=now() where id=v.module_id; update public.module_versions set lifecycle_state='active',activated_by=p_actor_id,activated_at=now() where id=v.id; elsif p_target_state='maintenance' then update public.modules set status='maintenance',updated_at=now() where id=v.module_id; update public.module_versions set lifecycle_state='maintenance' where id=v.id; elsif p_target_state='disabled' then update public.modules set status='disabled',updated_at=now() where id=v.module_id; update public.module_versions set lifecycle_state='disabled',retired_at=coalesce(retired_at,now()) where id=v.id; elsif p_target_state='validated' then update public.module_versions set lifecycle_state='validated',validated_by=p_actor_id,validated_at=now() where id=v.id; elsif p_target_state='tested' then update public.module_versions set lifecycle_state='tested',tested_by=p_actor_id,tested_at=now() where id=v.id; else select * into previous from public.module_versions where module_id=v.module_id and lifecycle_state in ('active','tested','validated','maintenance') and id<>v.id order by activated_at desc nulls last,created_at desc limit 1; update public.module_versions set lifecycle_state='rolled_back',retired_at=coalesce(retired_at,now()),reason=p_reason where id=v.id; if previous.id is not null then update public.module_versions set lifecycle_state='active',activated_by=p_actor_id,activated_at=now() where id=previous.id; update public.modules set active_version_id=previous.id,status='active',manifest=previous.manifest,config=previous.config,updated_at=now(),last_activity_at=now() where id=v.module_id; else update public.modules set active_version_id=null,status='rolled_back',updated_at=now() where id=v.module_id; end if; end if; insert into public.module_config_history(module_id,version_id,action,after_config,actor_id,reason) values(v.module_id,v.id,case when p_target_state='rolled_back' then 'rollback' else p_target_state end,v.config,p_actor_id,p_reason); insert into public.module_events(module_id,module_version_id,event_type,payload,actor_id) values(v.module_id,v.id,'module.lifecycle.'||p_target_state,jsonb_build_object('reason',p_reason),p_actor_id); select * into v from public.module_versions where id=v.id; return v; end; $$;
revoke all on function public.module_lifecycle_transition(uuid,text,uuid,text) from public,anon,authenticated; grant execute on function public.module_lifecycle_transition(uuid,text,uuid,text) to service_role;

do $$ declare a uuid; begin select id into a from public.agents where agent_key='module'; if a is null then raise exception 'Module agent not found'; end if; update public.agents set status='enabled',last_activity_at=now(),updated_at=now() where id=a; insert into public.agent_permissions(agent_id,permission,allowed,requires_approval) values(a,'agent.execute',true,false),(a,'modules.create',true,false),(a,'modules.validate',true,false),(a,'modules.test',true,false),(a,'modules.activate',true,false),(a,'modules.manage',true,false),(a,'modules.run',true,false),(a,'modules.artifacts',true,false),(a,'roles.modify',false,false),(a,'permissions.self_modify',false,false) on conflict(agent_id,permission) do update set allowed=excluded.allowed,requires_approval=excluded.requires_approval; end $$;
